  /// Token creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Token last update timestamp (e.g., when status changed).
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the token was used for email verification. Null if token
  /// is still pending or expired.
  used_at DateTime? @db.Timestamptz

  /// Token expiration timestamp (24 hours after creation).
  expired_at DateTime @db.Timestamptz

  /// Soft delete timestamp for archival purposes.
  deleted_at DateTime? @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  // spellchecker: ignore-next-line
