  //----
  // INDEXES
  //----
  @@unique([token])
  // spellchecker: ignore-next-line
  @@unique([ecommerce_mall_member_id, status], map: "ecommerce_mall_member_email_verifications_ecommerce_ma_d8d9c5d1")
  // spellchecker: ignore-next-line
  @@index([ecommerce_mall_member_id, created_at], map: "ecommerce_mall_member_email_verifications_ecommerce_ma_25b99d84")
