  creator ecommerce_mall_administrators? @relation(fields: [creator_id], references: [id], onDelete: Cascade)

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
  products                          ecommerce_mall_products[]
  children                          ecommerce_mall_categories[]           @relation("recursive")
  ecommerceMallCategoriesSnapshotss ecommerce_mall_snapshots[]
  productSnapshots                  ecommerce_mall_product_snapshots[]
  ecommerceMallCategorySnapshots    ecommerce_mall_categories_snapshots[] @relation("ecommerce_mall_categories_snapshots_of_category_id")
  childCategories                   ecommerce_mall_categories_snapshots[] @relation("ecommerce_mall_categories_snapshots_of_parent_category_id")

  @@unique([parent_id, name])
