  customerReviews                  ecommerce_mall_customer_reviews[]
  shipmentItems                    ecommerce_mall_shipment_items[]
  cancellationRequestItem          ecommerce_mall_cancellation_requests?
  refundRequestItem                ecommerce_mall_refund_requests?
