import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";
import api from "@ORGANIZATION/PROJECT-api";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IEcommerceMallGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallGuest";
import { authorize_guest_join } from "../../../authorize/authorize_guest_join";
import { authorize_guest_refresh } from "../../../authorize/authorize_guest_refresh";
export async function test_api_guest_join_new_account(connection: api.IConnection): Promise<void> {
  /**
   * Test the primary success path for new guest registration.
   *
   * Validates the complete guest registration flow including device fingerprint creation,
   * session establishment with IP and referrer tracking, and JWT token generation.
   * Tests both new guest registration and existing guest session continuation scenarios.
   *
   * Special attention is given to verifying that the access and refresh tokens are
   * properly generated with appropriate expiration times, and that the guest ID remains
   * consistent across multiple requests from the same device fingerprint.
   *
   * 1. Generate random guest registration data with unique fingerprint, valid IP, and href.
   * 2. Register new guest using authorize_guest_join utility function.
   * 3. Validate HTTP 201 response with valid JWT tokens and expiration timestamps.
   * 4. Verify guest ID is UUID format and tokens are valid JWT strings.
   * 5. Test duplicate fingerprint returns same guest ID (session continuation).
   * 6. Use access token from first registration for subsequent authenticated request.
   */

  // Generate random guest registration data
  const fingerprint = RandomGenerator.alphaNumeric(16);
  const href = typia.random<string & tags.Format<"uri">>();
  const ip = typia.random<string & tags.Format<"ipv4">>();
  const referrer = typia.random<string & tags.Format<"uri">>();

  // Step 1: Register new guest
  const joinConnection: api.IConnection = { host: connection.host };
  const joinResult = await authorize_guest_join(joinConnection, {
    body: {
      fingerprint,
      href,
      ip,
      referrer,
    } satisfies IEcommerceMallGuest.IJoin,
  });
  typia.assert(joinResult);

  // Step 2: Validate new guest registration response
  TestValidator.predicate("guest ID is UUID format", /^[0-9a-f-]{36}$/i.test(joinResult.id));
  TestValidator.predicate("access token is valid JWT format", joinResult.token.access.split(".").length === 3);
  TestValidator.predicate("refresh token is valid JWT format", joinResult.token.refresh.split(".").length === 3);
  TestValidator.predicate("expired_at timestamp exists", joinResult.token.expired_at !== undefined);
  TestValidator.predicate("refreshable_until timestamp exists", joinResult.token.refreshable_until !== undefined);

  // Step 3: Verify token expiration times are set (approximately 24 hours)
  const expiredAt = new Date(joinResult.token.expired_at);
  const refreshableUntil = new Date(joinResult.token.refreshable_until);
  const now = new Date();
  const twentyFourHours = 24 * 60 * 60 * 1000;

  TestValidator.predicate("expired_at is in future", expiredAt > now);
  TestValidator.predicate(
    "expired_at is approximately 24 hours from now",
    Math.abs(expiredAt.getTime() - now.getTime() - twentyFourHours) < 5 * 60 * 1000,
  );
  TestValidator.predicate("refreshable_until is after expired_at", refreshableUntil > expiredAt);

  // Step 4: Test duplicate fingerprint (session continuation for existing guest)
  const continuationConnection: api.IConnection = { host: connection.host };
  const continuationResult = await authorize_guest_join(continuationConnection, {
    body: {
      fingerprint,
      href: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IEcommerceMallGuest.IJoin,
  });
  typia.assert(continuationResult);

  // Verify same guest ID returned for duplicate fingerprint
  TestValidator.equals(
    "same guest ID for duplicate fingerprint registration",
    joinResult.id,
    continuationResult.id,
  );

  // Verify new session tokens were issued
  TestValidator.notEquals(
    "different session tokens for renewed session",
    joinResult.token.access,
    continuationResult.token.access,
  );

  // Step 5: Verify connection headers updated with auth token
  TestValidator.predicate(
    "connection has authorization header updated",
    joinConnection.headers?.authorization !== undefined,
  );
  TestValidator.equals(
    "authorization header contains Bearer token",
    joinConnection.headers?.authorization,
    `Bearer ${joinResult.token.access}`,
  );
}

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IEcommerceMallGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallGuest";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_guest_join } from "../../../authorize/authorize_guest_join";
import { authorize_guest_refresh } from "../../../authorize/authorize_guest_refresh";

export async function test_api_guest_join_session_continuity(
  connection: api.IConnection,
): Promise<void> {
  // Generate consistent fingerprint for both join calls
  const fingerprint = RandomGenerator.alphaNumeric(32);
  // First join: Create new guest account
  const firstJoinBody = {
    fingerprint,
    href: typia.random<string & tags.Format<"uri">>(),
    ip: typia.random<string & tags.Format<"ipv4">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IEcommerceMallGuest.IJoin;
  // Use authorize_guest_join utility function for first call
  const guestConnection: api.IConnection = { host: connection.host };
  const firstResult = await authorize_guest_join(guestConnection, {
    body: firstJoinBody,
  });
  typia.assert(firstResult);
  // Store first guest_id and token
  const firstGuestId = firstResult.id;
  const firstAccessToken = firstResult.token.access;
  const firstRefreshToken = firstResult.token.refresh;
  // Second join: Refresh existing guest session with different href
  const secondJoinBody = {
    fingerprint,
    href: typia.random<string & tags.Format<"uri">>(),
    ip: firstJoinBody.ip, // Same IP to maintain context
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IEcommerceMallGuest.IJoin;
  // Use authorize_guest_join utility function for second call
  const guestRefreshConnection: api.IConnection = { host: connection.host };
  const secondResult = await authorize_guest_join(guestRefreshConnection, {
    body: secondJoinBody,
  });
  typia.assert(secondResult);
  // Validate session continuity
  TestValidator.equals(
    "guest_id consistent across join calls",
    secondResult.id,
    firstGuestId,
  );
  // Tokens should be regenerated on second call for security
  TestValidator.notEquals(
    "access token regenerated on second call",
    firstAccessToken,
    secondResult.token.access,
  );
  TestValidator.notEquals(
    "refresh token regenerated on second call",
    firstRefreshToken,
    secondResult.token.refresh,
  );
  // Validate timestamp expiration is refreshed on second call
  const firstExpiredAt = new Date(firstResult.token.expired_at).getTime();
  const secondExpiredAt = new Date(secondResult.token.expired_at).getTime();
  TestValidator.predicate(
    "access token expiration refreshed on second call",
    secondExpiredAt > firstExpiredAt - 1000,
  );
  const firstRefreshableUntil = new Date(
    firstResult.token.refreshable_until,
  ).getTime();
  const secondRefreshableUntil = new Date(
    secondResult.token.refreshable_until,
  ).getTime();
  TestValidator.predicate(
    "refreshable_until deadline refreshed on second call",
    secondRefreshableUntil > firstRefreshableUntil - 1000,
  );
  // Validate guest_id is valid uuid format through typia type assertion
  typia.assert<string & tags.Format<"uuid">>(firstGuestId);
  typia.assert<string & tags.Format<"uuid">>(secondResult.id);
}

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IEcommerceMallGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallGuest";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_guest_join } from "../../../authorize/authorize_guest_join";
import { authorize_guest_refresh } from "../../../authorize/authorize_guest_refresh";

export async function test_api_guest_refresh_valid_token(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create guest account with initial join
  const joinConnection: api.IConnection = { host: connection.host };
  const guestJoin = await authorize_guest_join(joinConnection, {
    body: {
      fingerprint: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IEcommerceMallGuest.IJoin,
  });
  typia.assert(guestJoin);
  const oldRefreshToken = guestJoin.token.refresh;
  const oldExpiredAt = guestJoin.token.expired_at;
  const oldRefreshableUntil = guestJoin.token.refreshable_until;
  // 2. Create connection for refresh operation
  const refreshConnection: api.IConnection = { host: connection.host };
  // 3. Perform token refresh with valid refresh token
  const guestRefresh = await authorize_guest_refresh(refreshConnection, {
    body: {
      refresh: oldRefreshToken,
    } satisfies IEcommerceMallGuest.IRefresh,
  });
  typia.assert(guestRefresh);
  // 4. Validate token rotation - new refresh token differs from old
  TestValidator.notEquals(
    "refresh token rotated",
    oldRefreshToken,
    guestRefresh.token.refresh,
  );
  // 5. Validate new access token is returned
  TestValidator.predicate(
    "new access token exists",
    guestRefresh.token.access.length > 0,
  );
  // 6. Validate access token format (JWT-like: three base64 parts separated by dots)
  const jwtPattern = /^[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+$/;
  TestValidator.predicate(
    "access token is valid JWT format",
    jwtPattern.test(guestRefresh.token.access),
  );
  // 7. Validate expired_at is in the future (ISO 8601 date-time)
  TestValidator.predicate(
    "access expired_at is in the future",
    new Date(guestRefresh.token.expired_at) > new Date(),
  );
  // 8. Validate expired_at extends from old expiration (new expiration is later or same)
  TestValidator.predicate(
    "access token extended from previous",
    new Date(guestRefresh.token.expired_at) >= new Date(oldExpiredAt),
  );
  // 9. Validate refreshable_until is in the future
  TestValidator.predicate(
    "refreshable_until is in the future",
    new Date(guestRefresh.token.refreshable_until) > new Date(),
  );
  // 10. Validate refreshable_until extends from old deadline (or remains same for rotation)
  TestValidator.predicate(
    "refreshable_until extends from previous",
    new Date(guestRefresh.token.refreshable_until) >=
      new Date(oldRefreshableUntil),
  );
  // 11. Verify guest ID remains consistent across join and refresh
  TestValidator.equals("guest ID consistent", guestJoin.id, guestRefresh.id);
  // 12. Verify connection headers were updated with new access token
  const authHeader = refreshConnection.headers?.Authorization;
  TestValidator.predicate(
    "connection updated with new access token",
    typeof authHeader === "string" && authHeader.includes(guestRefresh.token.access),
  );
}

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IEcommerceMallGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallGuest";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_guest_join } from "../../../authorize/authorize_guest_join";
import { authorize_guest_refresh } from "../../../authorize/authorize_guest_refresh";

export async function test_api_guest_refresh_expired_token(
  connection: api.IConnection,
): Promise<void> {
  // Step 1: Register guest account with unique device fingerprint
  const guestConnection: api.IConnection = { host: connection.host };
  const joinResponse: IEcommerceMallGuest.IAuthorized =
    await authorize_guest_join(guestConnection, {
      body: {
        fingerprint: RandomGenerator.alphaNumeric(16),
        href: typia.random<string & tags.Format<"uri">>() satisfies string &
          tags.Format<"uri">,
        ip: typia.random<string & tags.Format<"ipv4">>() satisfies string &
          tags.Format<"ipv4">,
        referrer: typia.random<string & tags.Format<"uri">>() satisfies string &
          tags.Format<"uri">,
      } satisfies IEcommerceMallGuest.IJoin,
    });
  typia.assert(joinResponse);
  // Step 2: Extract refresh token from successful join response
  const refreshToken: string = joinResponse.token.refresh;
  const guestId: string & tags.Format<"uuid"> = joinResponse.id;
  // Step 3: Create a NEW connection to simulate fresh request with expired token
  const refreshedConnection: api.IConnection = { host: connection.host };
  // Step 4: Attempt to refresh with the same refresh token
  // This simulates the scenario where a guest tries to refresh an expired token
  const refreshBody: IEcommerceMallGuest.IRefresh = {
    refresh: refreshToken,
  } satisfies IEcommerceMallGuest.IRefresh;
  // Step 5: Expect the system to reject the expired token with appropriate error
  // The error should indicate the token is expired and re-registration is required
  await TestValidator.httpError(
    "expired refresh token should be rejected",
    [400, 401, 403],
    async () =>
      await authorize_guest_refresh(refreshedConnection, { body: refreshBody }),
  );
  // Step 6: Verify that re-registration is required to obtain new tokens
  // Call join again with the same fingerprint to get fresh tokens
  const rejoinConnection: api.IConnection = { host: connection.host };
  const rejoinResponse: IEcommerceMallGuest.IAuthorized =
    await authorize_guest_join(rejoinConnection, {
      body: {
