): Promise<void> {
  // 1. Register Alice (first customer)
  const aliceConnection: api.IConnection = { host: connection.host };
  const aliceResult = await authorize_member_join(aliceConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
