  const reviewsByDateAsc =
    await api.functional.ecommerceMall.member.member.reviews.index(
      memberConnection,
      {
        body: {
          page: 1,
          page_size: 100,
          sort_by: "created_at",
          sort_order: "asc",
        },
      },
    );
  typia.assert(reviewsByDateAsc);
