    TestValidator.predicate(
      "snapshot has valid category",
      sampleSnapshot.category !== null && sampleSnapshot.category !== undefined,
    );
    TestValidator.notEquals(
      "category has id",
      sampleSnapshot.category.id,
      null,
    );
  }
}

