  typia.assert(sortByCreatedAt);
  // 6. Test sorting by order_date ascending
  const sortByOrderDate =
    await api.functional.ecommerceMall.member.order_snapshots.index(
      memberConnection,
      {
        body: { sort_by: "order_date", sort_order: "asc" },
