        request.item.id !== undefined,
        true,
      );
      TestValidator.equals(
        "item order_number exists",
        request.item.order_number !== undefined,
        true,
      );
      TestValidator.equals(
        "item product_variant_name exists",
        request.item.product_variant_name !== undefined,
        true,
      );
      TestValidator.equals(
