    actor_type: "customer",
    response_status: "pending",
    limit: 10,
  } satisfies IEcommerceMallCancellationRequestSnapshot.IRequest;
  const pendingResult =
    await api.functional.ecommerceMall.seller.cancellation_request_snapshots.index(
      sellerConnection,
