    await api.functional.ecommerceMall.administrator.cancellation_request_snapshots.index(
      adminConnection,
      {
        body: {
          approved_at_range: approvedInRange,
          limit: 100,
        } satisfies IEcommerceMallCancellationRequestSnapshot.IRequest,
      },
    );
