import { authorize_member_login } from "../../../authorize/authorize_member_login";
import { authorize_member_refresh } from "../../../authorize/authorize_member_refresh";

export async function test_api_cancellation_request_snapshot_retrieval(
  connection: api.IConnection,
): Promise<void> {
  // Step 1: Register customer member account
  const joinConnection: api.IConnection = { host: connection.host };
  const joinedMember: IEcommerceMallMember.IAuthorized =
    await authorize_member_join(joinConnection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: RandomGenerator.alphaNumeric(16),
        display_name: RandomGenerator.name(),
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IEcommerceMallMember.IJoin,
    });
  typia.assert(joinedMember);

  // Step 2: Generate a random snapshot ID to test retrieval
  // In a real scenario, this would be an existing snapshot from the database
  const snapshotId: string & tags.Format<"uuid"> =
    typia.random<string & tags.Format<"uuid">>();

  // Step 3: Attempt to retrieve the cancellation request snapshot
  // This will either succeed (if snapshot exists) or fail with 404
  let snapshot: IEcommerceMallCancellationRequestSnapshot;
  try {
    snapshot = await api.functional.ecommerceMall.member.cancellation_request_snapshots.at(
      joinConnection,
      {
        id: snapshotId,
      },
    );
  } catch (error) {
    // Expected: 404 Not Found for non-existent snapshot
    // This is a valid test outcome for negative test case
    if (error instanceof api.HttpError && error.status === 404) {
      TestValidator.equals(
        "Non-existent snapshot should return 404",
        true,
        true,
      );
      return;
    }
    throw error;
  }

  // Step 4: Validate snapshot structure and required fields
  typia.assert(snapshot);

  // Validate basic snapshot fields
  TestValidator.equals("snapshot has valid ID", snapshot.id.length > 0, true);
  TestValidator.equals("snapshot has valid title", snapshot.title.length > 0, true);
  TestValidator.equals("snapshot has valid body", snapshot.body.length > 0, true);
  TestValidator.equals("snapshot has valid actorType", snapshot.actorType.length > 0, true);
  TestValidator.equals("snapshot has createdAt", snapshot.createdAt.length > 0, true);
  TestValidator.equals("snapshot has createdBy", snapshot.createdBy.length > 0, true);

  // Validate cancellationRequest reference
  TestValidator.equals(
    "snapshot has cancellationRequest reference",
    snapshot.cancellationRequest !== undefined,
    true,
  );
  typia.assert(snapshot.cancellationRequest);

  // Validate cancellationRequest fields
  TestValidator.equals(
    "cancellationRequest has valid ID",
    snapshot.cancellationRequest.id.length > 0,
    true,
  );
  TestValidator.equals(
    "cancellationRequest has reason",
    snapshot.cancellationRequest.reason.length > 0,
    true,
  );
  TestValidator.equals(
    "cancellationRequest has status",
    snapshot.cancellationRequest.status.length > 0,
    true,
  );
  TestValidator.equals(
    "cancellationRequest has created_at",
    snapshot.cancellationRequest.created_at.length > 0,
    true,
  );

  // Validate item reference exists
  TestValidator.equals(
    "cancellationRequest has item reference",
    snapshot.cancellationRequest.item !== undefined,
    true,
  );
  typia.assert(snapshot.cancellationRequest.item);

  // Validate order reference exists
  TestValidator.equals(
    "cancellationRequest has order reference",
    snapshot.cancellationRequest.order !== undefined,
    true,
  );
  typia.assert(snapshot.cancellationRequest.order);

  // Validate seller reference exists
  TestValidator.equals(
    "cancellationRequest has seller reference",
    snapshot.cancellationRequest.seller !== undefined,
    true,
  );
  typia.assert(snapshot.cancellationRequest.seller);

  // Validate seller response timestamps are mutually exclusive
  // Either approved_at is set OR rejected_at is set (or both null if pending)
  const hasApproval = snapshot.approvedAt !== null && snapshot.approvedAt !== undefined;
  const hasRejection =
    snapshot.rejectedAt !== null && snapshot.rejectedAt !== undefined;

  if (hasApproval && hasRejection) {
    // Invalid state - both should not be set
    throw new Error(
      "Snapshot cannot have both approvedAt and rejectedAt set",
    );
  }

  // If rejected, validate seller_rejection_reason exists
  if (hasRejection) {
    // seller_rejection_reason may be null even if rejected, depending on implementation
    // This is acceptable as long as rejected_at is set
    TestValidator.equals(
      "snapshot has seller rejection reason or null when rejected",
      snapshot.sellerRejectionReason === null ||
        snapshot.sellerRejectionReason !== undefined,
      true,
    );
  }

  // Validate approval timestamp format if set
  if (snapshot.approvedAt !== null && snapshot.approvedAt !== undefined) {
    TestValidator.predicate(
      "approvedAt is valid ISO 8601 datetime",
      () => !isNaN(Date.parse(snapshot.approvedAt!)),
    );
  }

  // Validate rejection timestamp format if set
  if (snapshot.rejectedAt !== null && snapshot.rejectedAt !== undefined) {
    TestValidator.predicate(
      "rejectedAt is valid ISO 8601 datetime",
      () => !isNaN(Date.parse(snapshot.rejectedAt!)),
    );
  }
}

