import { authorize_administrator_refresh } from "../../../authorize/authorize_administrator_refresh";
import { generate_random_ecommerce_mall_administrator_user_bans_create } from "../../../generate/generate_random_ecommerce_mall_administrator_user_bans_create";
import { prepare_random_ecommerce_mall_user_ban } from "../../../prepare/prepare_random_ecommerce_mall_user_ban";

export async function test_api_customer_ban_subtype_retrieval(
  connection: api.IConnection,
): Promise<void> {
  // 1. Administrator setup and authentication
  const adminConnection: api.IConnection = { host: connection.host };
  const adminAuthorized = await authorize_administrator_join(adminConnection, {
    body: {
      display_name: RandomGenerator.name(2),
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      grade: "regular" as const,
    } satisfies IEcommerceMallAdministrator.IJoin,
  });
  typia.assert(adminAuthorized);
  // Create fresh connection for admin operations using admin token
  const adminOperationConnection: api.IConnection = { host: connection.host };
  adminOperationConnection.headers = {
    Authorization: adminAuthorized.token.access,
  };
  // 2. Administrator creates a ban on a customer account
  const banResult =
    await api.functional.ecommerceMall.administrator.user_bans.create(
      adminOperationConnection,
      {
        body: {
          user_type: "customer" as const,
          customer_id: typia.random<string & tags.Format<"uuid">>(),
          reason: RandomGenerator.paragraph({ sentences: 2 }),
        } satisfies IEcommerceMallUserBan.ICreate,
      },
    );
  typia.assert(banResult);
  // Verify ban was created with customer type
  TestValidator.equals(
    "ban user_type is customer",
    banResult.user_type,
    "customer",
  );
  // 3. Retrieve the customer ban subtype record
  const banSubtype =
    await api.functional.ecommerceMall.administrator.user_ban_of_customers.at(
      adminOperationConnection,
      {
        banOfCustomerId: banResult.customerBan.id,
      },
    );
  typia.assert(banSubtype);
  // 4. Validate ban subtype record structure and data integrity
  // Verify ID consistency
  TestValidator.equals(
    "ban subtype id matches path parameter",
    banSubtype.id,
    banResult.customerBan.id,
  );
  TestValidator.equals(
    "ban subtype ban_id matches parent ban",
    banSubtype.ban.id,
    banResult.id,
  );
  // Verify ban metadata
  TestValidator.equals(
    "user_type is customer",
    banSubtype.ban.user_type,
    "customer",
  );
  TestValidator.equals(
    "ban reason matches parent ban",
    banSubtype.ban.reason,
    banResult.reason,
  );
  TestValidator.equals(
    "banned_at timestamp matches parent ban",
    banSubtype.ban.banned_at,
    banResult.banned_at,
  );
  TestValidator.equals(
    "administrator reference exists",
    banSubtype.ban.administrator.id !== undefined,
    true,
  );
