  const yesterday = new Date(now.getTime() - 24 * 60 * 60 * 1000);
  const dateRangeFilter: IEcommerceMallSellerApprovalRequest.IRequest = {
    status: ["pending"],
    created_at_gte: yesterday.toISOString(),
    created_at_lte: now.toISOString(),
