export async function test_api_administrator_approval_requests_listing(
  connection: api.IConnection,
): Promise<void> {
  // 1. Super Administrator Authentication
  const superAdminConnection: api.IConnection = { host: connection.host };
  const superAdminAuth = await authorize_super_administrator_join(
    superAdminConnection,
    {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        display_name: RandomGenerator.name(2),
        password: RandomGenerator.alphaNumeric(16),
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
        ip: typia.random<string & tags.Format<"ipv4">>() ?? null,
      } satisfies IEcommerceMallSuperAdministrator.IJoin,
    },
  );
  typia.assert(superAdminAuth);
  // Create connection with super admin token
  const authenticatedConnection: api.IConnection = {
    host: connection.host,
    headers: {
      Authorization: superAdminAuth.token.access,
    },
  };
  // 2. Test Primary Success Path - List all requests with default parameters
  const defaultResponse =
    await api.functional.ecommerceMall.superAdministrator.administration_requests.index(
      authenticatedConnection,
      {
        body: {} satisfies IEcommerceMallAdministratorApprovalRequests.IRequest,
      },
    );
  typia.assert(defaultResponse);
  // Validate pagination structure constraints
  TestValidator.predicate(
    "current page is positive",
    defaultResponse.pagination.current >= 1,
  );
  TestValidator.predicate(
    "limit is within valid range",
    defaultResponse.pagination.limit >= 1 &&
      defaultResponse.pagination.limit <= 100,
  );
  TestValidator.predicate(
    "pages matches records/limit calculation",
    defaultResponse.pagination.pages ===
      Math.ceil(
        defaultResponse.pagination.records / defaultResponse.pagination.limit,
      ),
  );
  TestValidator.predicate(
    "records matches array length",
    defaultResponse.pagination.records === defaultResponse.data.length,
  );
  // Validate data array structure
  if (defaultResponse.data.length > 0) {
    const firstRequest = defaultResponse.data[0];
    // Verify required fields exist and have valid formats
    TestValidator.predicate(
      "request has valid status",
      ["pending", "approved", "rejected"].includes(firstRequest.status),
    );
    TestValidator.predicate(
      "request has non-empty reason",
      firstRequest.reason.length > 0,
    );
    TestValidator.predicate(
      "request has valid created_at",
      !isNaN(Date.parse(firstRequest.created_at)),
    );
    TestValidator.predicate(
      "request has valid updated_at",
      !isNaN(Date.parse(firstRequest.updated_at)),
    );
    // Verify timestamp order
    TestValidator.predicate(
      "updated_at is not before created_at",
      new Date(firstRequest.updated_at) >= new Date(firstRequest.created_at),
    );
    // Verify soft delete filter - deleted_at should be null
    TestValidator.equals(
      "no soft deleted records",
      firstRequest.deleted_at,
      null,
    );
  }
  // 3. Test Custom Pagination Limit
  const limitedResponse =
    await api.functional.ecommerceMall.superAdministrator.administration_requests.index(
      authenticatedConnection,
      {
        body: {
          limit: 10,
        } satisfies IEcommerceMallAdministratorApprovalRequests.IRequest,
      },
    );
  typia.assert(limitedResponse);
  TestValidator.equals(
    "custom limit applied",
    limitedResponse.pagination.limit,
    10,
  );
  // 4. Test Status Filtering - pending requests only
  const pendingResponse =
    await api.functional.ecommerceMall.superAdministrator.administration_requests.index(
      authenticatedConnection,
      {
        body: {
          status: "pending",
        } satisfies IEcommerceMallAdministratorApprovalRequests.IRequest,
      },
    );
  typia.assert(pendingResponse);
  // Verify all returned requests have pending status
  if (pendingResponse.data.length > 0) {
    pendingResponse.data.forEach((request, index) => {
      TestValidator.equals(
        `pending request ${index} status`,
        request.status,
        "pending",
      );
    });
  }
  // 5. Test Status Filtering - approved requests only
  const approvedResponse =
    await api.functional.ecommerceMall.superAdministrator.administration_requests.index(
      authenticatedConnection,
      {
        body: {
          status: "approved",
        } satisfies IEcommerceMallAdministratorApprovalRequests.IRequest,
      },
    );
  typia.assert(approvedResponse);
  // Verify all returned requests have approved status
  if (approvedResponse.data.length > 0) {
    approvedResponse.data.forEach((request, index) => {
      TestValidator.equals(
        `approved request ${index} status`,
        request.status,
        "approved",
      );
    });
  }
  // 6. Test Status Filtering - rejected requests only
  const rejectedResponse =
    await api.functional.ecommerceMall.superAdministrator.administration_requests.index(
      authenticatedConnection,
      {
        body: {
          status: "rejected",
        } satisfies IEcommerceMallAdministratorApprovalRequests.IRequest,
      },
    );
  typia.assert(rejectedResponse);
  // Verify all returned requests have rejected status
  if (rejectedResponse.data.length > 0) {
    rejectedResponse.data.forEach((request, index) => {
      TestValidator.equals(
        `rejected request ${index} status`,
        request.status,
        "rejected",
      );
    });
  }
  // 7. Test Sorting - oldest_first
  const oldestFirstResponse =
    await api.functional.ecommerceMall.superAdministrator.administration_requests.index(
      authenticatedConnection,
      {
