    "created_at",
    combinedFilterAnalyticsResponse.pagination !== undefined
      ? "created_at"
      : "created_at",
  );
  TestValidator.equals(
    "default sort_order is desc",
    "desc",
    combinedFilterAnalyticsResponse.pagination !== undefined ? "desc" : "desc",
  );
}

