export async function getEcommerceMallAdministratorUserBanOfSellersBanOfSellerId(props: {
  administrator: AdministratorPayload;
  banOfSellerId: string & tags.Format<"uuid">;
}): Promise<IEcommerceMallUserBanOfSeller> {
