  };
  const data =
    await MyGlobal.prisma.ecommerce_mall_seller_approval_requests.findMany({
      where: whereInput,
      skip,
      take: limit,
      orderBy:
        props.body.sort_by === "created_at"
          ? { created_at: (props.body.order ?? "desc") as "asc" | "desc" }
          : props.body.sort_by === "updated_at"
