import { IEcommerceMallCategoriesStatistic } from "../../../../api/structures/IEcommerceMallCategoriesStatistic";
import { IEcommerceMallCategory } from "../../../../api/structures/IEcommerceMallCategory";
import { AdministratorAuth } from "../../../../decorators/AdministratorAuth";
import { AdministratorPayload } from "../../../../decorators/payload/AdministratorPayload";
import { deleteEcommerceMallAdministratorCategoriesCategoryId } from "../../../../providers/deleteEcommerceMallAdministratorCategoriesCategoryId";
import { getEcommerceMallAdministratorCategoriesCategoryIdStats } from "../../../../providers/getEcommerceMallAdministratorCategoriesCategoryIdStats";
import { getEcommerceMallAdministratorCategoriesHierarchy } from "../../../../providers/getEcommerceMallAdministratorCategoriesHierarchy";
import { patchEcommerceMallAdministratorCategoriesCategoryId } from "../../../../providers/patchEcommerceMallAdministratorCategoriesCategoryId";
import { postEcommerceMallAdministratorCategories } from "../../../../providers/postEcommerceMallAdministratorCategories";
import { putEcommerceMallAdministratorCategoriesCategoryId } from "../../../../providers/putEcommerceMallAdministratorCategoriesCategoryId";

@Controller("/ecommerceMall/administrator/categories")
export class EcommercemallAdministratorCategoriesController {
  /**
   * Create a new product category for catalog organization.
   *
   * Creates a new category that organizes products for customer browsing. The category requires a name and description, and can optionally be assigned as a subcategory under an existing parent category (one level of nesting only). The system automatically records the administrator who created the category and generates immutable audit snapshots.
   *
   * **Permissions**: Administrator or super administrator role required.
   *
   * **Validation**: Name is required. Name must be unique within the parent category scope (if parent_id provided). Description is required.
   *
   * **Audit**: Creates a snapshot record capturing the new category's state.
   *
   * @param connection
   * @param body Category creation data including name, description, optional parent category reference, and display order priority. Name and description are required fields. Parent ID must reference an existing category that has no parent (top-level category only, one-level nesting constraint).
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor administrator
   * @x-autobe-specification Create a new category record in ecommerce_mall_categories table.
   *
   * 1. Verify the requesting user has administrator or super administrator role.
   * 2. Validate request body:
   *    - name: Required, non-empty, max 100 characters, unique combined with parent_id
   *    - description: Required, max 500 characters
   *    - parent_id: Optional, must reference existing category (if provided)
   *    - sort_order: Optional, integer, defaults to 0 if not provided
   * 3. Validate nesting constraint: parent category cannot itself have a parent (one-level nesting only)
   * 4. Generate new UUID for id field
   * 5. Set creator_id to the requesting administrator's ID
   * 6. Set created_at and updated_at to current timestamp
   * 7. Set deleted_at to NULL (active category)
   * 8. Insert record into ecommerce_mall_categories table
   * 9. Create snapshot record in ecommerce_mall_categories_snapshots table with full category state
   * 10. Return the created category with all fields
   *
   * Error handling:
   * - 403: User lacks administrator privileges
   * - 400: Validation failed (empty name, empty description, invalid parent_id, nesting depth exceeded, name not unique within parent scope)
   * - 404: Parent category not found (if parent_id provided)
   * - 500: Database error during insert or snapshot creation
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post()
  public async create(
    @AdministratorAuth()
    administrator: AdministratorPayload,
    @TypedBody()
    body: IEcommerceMallCategory.ICreate,
  ): Promise<IEcommerceMallCategory> {
    try {
      return await postEcommerceMallAdministratorCategories({
        administrator,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Update an existing category's name, description, sort order, or parent category assignment.
   *
   * Only administrators can update categories. The category name must be unique within the same parent category level. When updating the parent category, the new hierarchy must not exceed one level of nesting (subcategories cannot have their own subcategories).
   *
   * The operation creates a snapshot of the category state before the change, recording the administrator's identity and timestamp for audit purposes. Categories with active products should use soft delete rather than hard deletion.
   *
   * @param connection
   * @param categoryId UUID of the category to update
   * @param body Category update data including name, description, sort order, and parent category assignment.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor administrator
   * @x-autobe-specification 1. Verify user has administrator privileges
   * 2. Validate categoryId exists and is not soft-deleted
   * 3. Validate required fields: name (non-empty string, max 100 chars)
   * 4. Validate optional fields: description (max 500 chars), sort_order (integer), parent_id (UUID or null)
   * 5. Check composite unique constraint: [parent_id, name] must be unique
   * 6. Validate one-level nesting: cannot assign a category as its own parent or create cycles
   * 7. Validate hierarchy: subcategory cannot be assigned as parent to another subcategory (max 1 level nesting)
   * 8. Create snapshot of current category state with administrator identity and timestamp
   * 9. Update category fields: name, description, sort_order, parent_id
   * 10. Update updated_at timestamp
   * 11. Return full updated category
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Put(":categoryId")
  public async putByCategoryid(
    @AdministratorAuth()
    administrator: AdministratorPayload,
    @TypedParam("categoryId")
    categoryId: string & tags.Format<"uuid">,
    @TypedBody()
    body: IEcommerceMallCategory.IUpdate,
  ): Promise<IEcommerceMallCategory> {
    try {
      return await putEcommerceMallAdministratorCategoriesCategoryId({
        administrator,
        categoryId,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Update an existing product category's attributes.
   *
   * Allows administrators to modify category name, description, sort order, and parent category assignment. All edits create audit snapshots for compliance tracking.
   *
   * **Requirements**:
   * - User must have administrator role
   * - Category name must be provided if explicitly included in request
   * - Parent category must exist if parent_id is included
   * - One-level nesting only: cannot assign subcategory as parent
   *
   * **Behavior**:
   * - Updates specified fields only; unspecified fields remain unchanged
   * - Creates snapshot of pre-update category state
   * - Updates updated_at timestamp
   * - Validates parent_id reference if provided
   * - Maintains unique constraint on [parent_id, name]
   *
   * @param connection
   * @param categoryId UUID identifier of the category to update.
   * @param body Update fields for category attributes. Any field may be omitted to leave it unchanged. If name is included, it must be non-empty string (max 100 characters). If parent_id is included, it must reference an existing top-level category.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor administrator
   * @x-autobe-specification 1. Verify user has administrator role (administrator or superAdministrator)
   * 2. Fetch category by categoryId from ecommerce_mall_categories
   * 3. Validate category exists and not soft-deleted (deleted_at IS NULL)
   * 4. Validate parent_id if provided:
   *    - Parent must exist in ecommerce_mall_categories
   *    - Parent must not be the same as the category itself
   *    - Parent cannot have a parent (one-level nesting: parent.parent_id must be NULL)
   * 5. Validate name uniqueness if included: {parent_id, name} must be unique across categories
   * 6. Prepare update object with non-null fields from requestBody
   * 7. Execute update on category record, updating updated_at timestamp
   * 8. Insert snapshot record into ecommerce_mall_categories_snapshots capturing pre-update state
   * 9. Return updated category entity with all fields
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Patch(":categoryId")
  public async patchByCategoryid(
    @AdministratorAuth()
    administrator: AdministratorPayload,
    @TypedParam("categoryId")
    categoryId: string & tags.Format<"uuid">,
    @TypedBody()
    body: IEcommerceMallCategory.IUpdate,
  ): Promise<IEcommerceMallCategory> {
    try {
      return await patchEcommerceMallAdministratorCategoriesCategoryId({
        administrator,
        categoryId,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Soft-delete a product category from the platform.
   *
   * Only administrators can delete categories. When a category is deleted, it is marked with a soft delete timestamp (deleted_at) rather than being physically removed, preserving product relationships and enabling audit trails.
   *
   * **Important**: Deleted categories cannot be recovered. All products in the deleted category become uncategorized but remain visible in the system and can be reassigned to a different category.
   *
   * **Authorization**: Requires administrator role. Regular customers and sellers cannot delete categories.
   *
   * @param connection
   * @param categoryId UUID of the category to delete (global scope)
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor administrator
   * @x-autobe-specification 1. Validate that the requesting user has administrator role
   * 2. Verify category exists by ID and is not already deleted (deleted_at is NULL)
   * 3. Return 404 if category not found
   * 4. Return 400 if category is already deleted (soft-deleted)
   * 5. Create a snapshot record in ecommerce_mall_categories_snapshots capturing:
   *    - category_id, name, description, parent_id (from the category being deleted)
   *    - entity_type = 'category'
   *    - modified_by_id = requesting administrator's ID
   *    - created_at = current timestamp
   * 6. Perform soft deletion: UPDATE ecommerce_mall_categories SET deleted_at = now() WHERE id = categoryId
   * 7. Log the deletion with administrator identity and timestamp
   * 8. Return 204 No Content (standard DELETE response)
   *
   * Error handling:
   * - 401 Unauthorized: Requesting user is not authenticated
   * - 403 Forbidden: User is not an administrator
   * - 404 Not Found: Category with given ID does not exist
   * - 400 Bad Request: Category is already deleted or deletion fails validation
   *
   * Business rules:
   * - Category deletion does not affect existing orders containing products from this category
   * - Products that become uncategorized remain searchable and visible
   * - All snapshot records reference the deleted category via FK cascade
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Delete(":categoryId")
  public async erase(
    @AdministratorAuth()
    administrator: AdministratorPayload,
    @TypedParam("categoryId")
    categoryId: string & tags.Format<"uuid">,
  ): Promise<void> {
    try {
      return await deleteEcommerceMallAdministratorCategoriesCategoryId({
        administrator,
        categoryId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Retrieve statistical metrics for a specific category including product counts, order statistics, and engagement data.
   *
   * **Purpose**:
   * This endpoint provides a comprehensive view of category performance and contents. It returns aggregated statistics that help administrators monitor category health and enables customers to understand category popularity.
   *
   * **Data Included**:
   * - Total number of products in the category
   * - Active and inactive product counts
   * - Total orders containing category products
   * - Total customers who purchased from this category
   * - Average product rating (if reviews exist)
   *
   * **Security**:
   * Access is granted to all authenticated users. Administrators see additional internal metrics.
   *
   * @param connection
   * @param categoryId UUID of the category to retrieve statistics for.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor administrator
   * @x-autobe-specification Query the ecommerce_mall_categories table for the specified categoryId.
   *
   * **Database Operations**:
   * 1. Fetch category by UUID from ecommerce_mall_categories where id = {categoryId} AND deleted_at IS NULL
   * 2. Join with ecommerce_mall_products table to count products where category_id = {categoryId} AND deleted_at IS NULL
   * 3. Join with ecommerce_mall_order_items and ecommerce_mall_orders to count orders containing products from this category
   * 4. Aggregate review statistics from ecommerce_mall_reviews for products in this category
   * 5. Return aggregated statistics in ICategoriesStatistics.IStats format
   *
   * **Business Rules**:
   * - Category must be soft-deleted (deleted_at IS NULL) to return statistics
   * - If category is soft-deleted, return 404 Not Found
   * - Product counts should exclude soft-deleted products
   * - Empty categories (zero products) return valid stats with zero counts
   * - Guest users (if any) are not authenticated; require login
   *
   * **Edge Cases**:
   * - Category not found: Return 404
   * - Category with no products: Return valid statistics with zero counts
   * - Category with deleted_at set: Return 404
   * - Permission denied: Return 403 if user lacks authentication
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Get(":categoryId/stats")
  public async stats(
    @AdministratorAuth()
    administrator: AdministratorPayload,
    @TypedParam("categoryId")
    categoryId: string & tags.Format<"uuid">,
  ): Promise<IEcommerceMallCategoriesStatistic.IStat> {
    try {
      return await getEcommerceMallAdministratorCategoriesCategoryIdStats({
        administrator,
        categoryId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Retrieve the complete hierarchical category structure with parent categories and their nested subcategories.
   *
   * This endpoint returns all active categories (not soft-deleted) organized in a tree structure where each parent category includes an array of its direct child subcategories. The hierarchy supports one level of nesting only, meaning subcategories cannot have their own children.
   *
   * Top-level categories (those with NULL parent_id) are returned as the root nodes, with their subcategories nested in the children array. Each category includes full details (id, name, description, sort_order, created_at, updated_at) and optionally the count of products in that category.
   *
   * Categories are sorted by parent_id (top-level first), then by sort_order within each level, with a stable fallback on name for consistent ordering.
   *
   * @param connection
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor administrator
   * @x-autobe-specification Query ecommerce_mall_categories table for active categories where deleted_at IS NULL.
   *
   * 1. Fetch all categories with their parent_id and sort_order fields
   * 2. Build hierarchical tree structure:
   *    - Group categories by parent_id
   *    - Top-level categories have parent_id = NULL
   *    - Child categories are grouped under their parent in the children array
   * 3. Apply ordering:
   *    - Primary: parent_id NULL values first (top-level), then by parent_id
   *    - Secondary: sort_order (NULL treated as 0) ascending
   *    - Tertiary: name ascending for stable ordering when sort_order is equal
   * 4. For each category in the tree, optionally include product count via LEFT JOIN with ecommerce_mall_products
   * 5. Return the complete tree structure with parent and nested children
   *
   * Error handling:
   * - Return 404 if no categories exist in the system
   * - Handle soft-deleted categories by excluding them (deleted_at IS NULL filter)
   * - Ensure no circular references in tree structure (system enforces one-level nesting)
   *
   * Performance considerations:
   * - Use recursive query or application-level tree building
   * - Consider caching for frequently accessed category trees
   * - Apply LIMIT/OFFSET only if pagination is needed at tree level
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Get("hierarchy")
  public async hierarchy(
    @AdministratorAuth()
    administrator: AdministratorPayload,
  ): Promise<IEcommerceMallCategory.IHierarchy> {
    try {
      return await getEcommerceMallAdministratorCategoriesHierarchy({
        administrator,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

