   * - 403 if caller lacks administrator permission
   *
   * Security: Verify caller has administrator or super administrator role before returning data.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Get(":banOfCustomerId")
  public async at(
