import { patchEcommerceMallAdministratorSellerApprovalRequests } from "../../../../providers/patchEcommerceMallAdministratorSellerApprovalRequests";
import { patchEcommerceMallAdministratorSellerApprovalRequestsRequestId } from "../../../../providers/patchEcommerceMallAdministratorSellerApprovalRequestsRequestId";

@Controller("/ecommerceMall/administrator/seller-approval-requests")
export class EcommercemallAdministratorSeller_approval_requestsController {
  /**
   * List seller approval requests with filtering, pagination, and sorting options.
   *
   * Retrieves a paginated list of seller registration approval requests with support for filtering by status, seller identity, reviewer assignment, and date ranges. Administrators use this endpoint to review pending seller applications, view all requests, and track approval workflow status.
   *
   * The response includes summary information for each approval request, optimized for list display. Full request details can be retrieved using the at operation with the request ID.
   *
   * Filtering allows administrators to focus on specific request statuses or date ranges. Sorting enables ordering by creation date, review date, or status for efficient workflow management.
   *
   * @param connection
   * @param body Search criteria for seller approval requests including status filter, date ranges, sorting options, and pagination parameters.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor administrator
   * @x-autobe-specification Query ecommerce_mall_seller_approval_requests table with filtering and pagination.
   *
   * Filtering:
   * - Optional status filter: pending, approved, or rejected
   * - Optional seller_id filter for requests from specific seller
   * - Optional reviewer_id filter for requests reviewed by specific administrator
   * - Optional date range filters on created_at and updated_at
   * - Optional status filter for multiple values (pending, approved, rejected)
   * - Soft delete filter: exclude records where deleted_at is not null
   *
   * Sorting:
   * - Default: created_at DESC (newest first)
   * - Supported: status, created_at, updated_at, reviewer_id
   *
   * Pagination:
   * - Cursor-based pagination for efficient large dataset browsing
   * - Default page size: 20 items per page
   * - Max page size: 100 items per page
   * - Support for forward and backward pagination
   *
   * Business Rules:
   * - Only return active requests (deleted_at IS NULL)
   * - Include snapshot relationship for each request
   * - Denormalized seller information for display purposes (seller display_name, email)
   * - If status is 'pending', reviewer_id and reviewer information will be null
   * - If status is 'rejected', rejection_reason is included in summary
   *
   * Edge Cases:
   * - Empty result set: return empty list with pagination metadata
   * - Invalid status values: reject request with validation error
   * - Invalid pagination parameters: default to safe values (page 0, size 20)
   * - No filtering: return all requests with default sorting and pagination
   *
   * Error Handling:
   * - 400: Invalid status value, invalid pagination parameters
   * - 401: Unauthorized if user not logged in as administrator
   * - 500: Database query error
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Patch()
  public async index(
    @AdministratorAuth()
    administrator: AdministratorPayload,
    @TypedBody()
    body: IEcommerceMallSellerApprovalRequest.IRequest,
  ): Promise<IPageIEcommerceMallSellerApprovalRequest.ISummary> {
    try {
      return await patchEcommerceMallAdministratorSellerApprovalRequests({
        administrator,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Retrieves a specific seller approval request by unique identifier.
   *
   * This endpoint returns the complete approval request record including the seller's information, current approval status, request reason, and reviewer details if the request has been reviewed. The response includes all temporal fields for audit purposes (created_at, updated_at, deleted_at).
   *
   * **Access Control**
   * Only platform administrators can access this endpoint. Guest users, customers, and sellers are denied access.
   *
   * @param connection
   * @param requestId Unique identifier of the seller approval request to retrieve
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor administrator
   * @x-autobe-specification Query ecommerce_mall_seller_approval_requests table for the record matching the path parameter requestId.
   *
   * 1. Fetch the approval request by id (UUID) from the database.
   * 2. If record not found (404), return error with message 'Approval request not found'.
   * 3. If record is soft-deleted (deleted_at is not null), return 404.
   * 4. Join with ecommerce_mall_sellers table to include seller information: id, email, display_name, approval_status.
   * 5. If reviewer_id is present, join with ecommerce_mall_administrators table to include reviewer information: id, display_name.
   * 6. Return full approval request entity with all fields including request_reason, rejection_reason, status, and timestamps.
   * 7. Do not include the snapshot relationship in the response to prevent excessive data loading.
   *
   * **Authorization**
   * Ensure the authenticated user has administrator role (administrator or superAdministrator). Return 403 Forbidden if unauthorized.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Get(":requestId")
  public async at(
    @AdministratorAuth()
    administrator: AdministratorPayload,
    @TypedParam("requestId")
    requestId: string & tags.Format<"uuid">,
  ): Promise<IEcommerceMallSellerApprovalRequest> {
    try {
      return await getEcommerceMallAdministratorSellerApprovalRequestsRequestId(
        {
          administrator,
          requestId,
        },
      );
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Update a seller approval request by approving or rejecting the application.
   *
   * Administrators can change the status of a pending seller approval request to either approved or rejected. When approving, the seller account is activated for selling. When rejecting, a detailed rejection reason must be provided to inform the seller why their application was denied. The approval decision is immutable once made - approved or rejected requests cannot be modified, requiring sellers to submit new applications for changes.
   *
   * @param connection
   * @param requestId UUID identifier of the seller approval request to update. The request must be in pending status and accessible by the requesting Administrator.
   * @param body Approval decision including status change, reviewer assignment, and rejection reason (when rejecting the application).
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor administrator
   * @x-autobe-specification Update seller approval request status and reviewer assignment.
   *
   * 1. Validation:
   *    - Verify request exists and is not soft-deleted
   *    - Verify current status is 'pending' (cannot modify approved or rejected requests)
   *    - Verify requester is an Administrator or SuperAdministrator actor
   *
   * 2. Business Rules:
   *    - If status is set to 'approved':
   *      - Verify status parameter equals 'approved'
   *      - reviewer_id is set to the requesting administrator's ID
   *      - rejection_reason must be null
   *    - If status is set to 'rejected':
   *      - Verify status parameter equals 'rejected'
   *      - reviewer_id is set to the requesting administrator's ID
   *      - rejection_reason is required (non-empty string)
   *
   * 3. Database Operations:
   *    - Update ecommerce_mall_seller_approval_requests table with:
   *      - status: new approval status
   *      - reviewer_id: administrator ID
   *      - rejection_reason: provided when rejecting
   *      - updated_at: current timestamp
   *    - Do NOT update: id, seller_id, request_reason, created_at, deleted_at
   *
   * 4. Audit Trail:
   *    - Create snapshot in ecommerce_mall_seller_approval_requests_snapshots table
   *    - Copy all fields from parent approval request to snapshot
   *    - Snapshot created_at = current timestamp
   *    - Snapshot is immutable audit record
   *
   * 5. Response:
   *    - Return full updated approval request entity
   *    - Include updated status, reviewer_id, and rejection_reason
   *
   * 6. Error Handling:
   *    - 404 Not Found: Request ID does not exist or is soft-deleted
   *    - 403 Forbidden: Request is not in pending status
   *    - 403 Forbidden: Requester lacks Administrator or SuperAdministrator role
   *    - 400 Bad Request: Invalid status value (must be 'approved' or 'rejected')
   *    - 400 Bad Request: Rejection reason required when status is 'rejected'
   *    - 400 Bad Request: Rejection reason provided when status is 'approved'
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Patch(":requestId")
  public async update(
    @AdministratorAuth()
    administrator: AdministratorPayload,
    @TypedParam("requestId")
    requestId: string & tags.Format<"uuid">,
    @TypedBody()
    body: IEcommerceMallSellerApprovalRequest.IUpdate,
  ): Promise<IEcommerceMallSellerApprovalRequest> {
    try {
      return await patchEcommerceMallAdministratorSellerApprovalRequestsRequestId(
        {
          administrator,
          requestId,
          body,
        },
      );
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

