   *    - reviewer: authenticated super admin ID
   *    - requester_id: requesting_member_id or requesting_seller_id
   *    - requester_type: 'member' or 'seller'
   *    - request_reason: original reason from approval request
   *    - status: 'approved' or 'rejected'
   *    - approved_grade: 'regular' (if approved, else null)
   *    - review_reason: rejection reason (if rejected, else null)
   *    - created_at: current timestamp
   * 8. Set reviewing_super_admin_id to the super admin's ID
   * 9. Update updated_at timestamp
   * 10. Return the updated approval request with complete relationships
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Patch(":requestId")
